  void RefreshAddresses(){if(lanAddressBox==null||lanAddressBox.IsDisposed)return;string old=CurrentLanIP();lanAddressBox.Items.Clear();try{foreach(var item in NetworkInfo.Addresses())lanAddressBox.Items.Add(item);}catch(Exception ex){AddLog("网卡地址读取失败："+ex.Message);}if(lanAddressBox.Items.Count>0){int index=0;for(int i=0;i<lanAddressBox.Items.Count;i++)if(((LanAddress)lanAddressBox.Items[i]).Address==old)index=i;lanAddressBox.SelectedIndex=index;}UpdateNetworkStatus();}
  string CurrentLanIP(){var address=lanAddressBox==null||lanAddressBox.IsDisposed?null:lanAddressBox.SelectedItem as LanAddress;return address==null?"":address.Address;}
  void UpdateNetworkStatus(){if(networkStatus==null||networkStatus.IsDisposed)return;string ip=CurrentLanIP();networkStatus.Text=ip==""?"未检测到 IPv4 私网地址，请先连接 Wi-Fi / 有线网络。":ip+":"+store.State.Port+"  ·  "+(store.State.AllowLan?(engine.Running?"共享运行中":"已设置，需启动内核"):"共享未开启")+"  ·  "+(store.State.LanAuthentication?"需要验证":"无需验证");}
  void SaveLan(){try{bool enabled=lanEnabled.Checked,auth=lanAuth.Checked;string user=lanUser.Text.Trim(),password=lanPassword.Text;Config.ValidateLan(enabled,auth,user,password);bool changed=enabled!=store.State.AllowLan||auth!=store.State.LanAuthentication||user!=store.State.LanUser||password!=store.State.LanPassword;if(engine.Running&&changed)throw new InvalidOperationException("请先在概览停止内核，再保存局域网设置；保存后重新启动。");bool oldEnabled=store.State.AllowLan,oldAuth=store.State.LanAuthentication;string oldUser=store.State.LanUser,oldPassword=store.State.LanPassword;store.State.AllowLan=enabled;store.State.LanAuthentication=auth;store.State.LanUser=user;store.State.LanPassword=password;try{store.Save();}catch{store.State.AllowLan=oldEnabled;store.State.LanAuthentication=oldAuth;store.State.LanUser=oldUser;store.State.LanPassword=oldPassword;throw;}UpdateNetworkStatus();AddLog("局域网共享设置已保存。"+(enabled?"启动内核后生效。":"共享已关闭。"));activity.Text="SAVED  /  共享设置已保存";}catch(Exception ex){Error(ex);}}
  void CopyLanAddress(){try{string ip=CurrentLanIP();if(ip=="")throw new InvalidOperationException("请先连接局域网并刷新地址。");Clipboard.SetText(ip+":"+store.State.Port);activity.Text="COPIED  /  代理地址已复制";}catch(Exception ex){Error(ex);}}
  void ShowLanHelp(){string ip=CurrentLanIP();if(ip=="")ip="本机的局域网 IPv4 地址";using(var dialog=new Form(){Text="局域网连接说明",ClientSize=new Size(660,510),StartPosition=FormStartPosition.CenterParent,Font=Theme.Font(9),MinimizeBox=false,MaximizeBox=false}){
   var text=new TextBox(){Multiline=true,ReadOnly=true,ScrollBars=ScrollBars.Vertical,Dock=DockStyle.Fill,BorderStyle=BorderStyle.None,Text=NetworkInfo.Instructions(ip,store.State,engine.Running)};var buttons=Row();buttons.Dock=DockStyle.Bottom;buttons.Padding=new Padding(16,5,0,0);buttons.Controls.Add(Button("复制说明",delegate{try{Clipboard.SetText(text.Text);}catch(Exception ex){MessageBox.Show(dialog,ex.Message);}},true,116));var close=new SoftButton(){Text="关闭",DialogResult=DialogResult.Cancel};buttons.Controls.Add(close);dialog.Controls.Add(text);dialog.Controls.Add(buttons);dialog.Padding=new Padding(22);dialog.CancelButton=close;Theme.Apply(dialog);dialog.ShowDialog(this);
  }}
  void ConnectionsPage(){var stack=Stack();content.Controls.Add(stack);var row=Row();row.Controls.Add(Button("刷新连接",RefreshConnections,false,116));connectionCount=Label("每 2 秒刷新 · 活跃连接 0",9,true);connectionCount.Margin=new Padding(10,10,0,0);row.Controls.Add(connectionCount);Add(stack,row,58);
   var card=new Surface(){Padding=new Padding(14),Margin=new Padding(0,0,0,14)};connections=List("目标地址","来源设备","协议","规则","上传 / 下载");connections.Columns[0].Width=245;connections.Columns[1].Width=155;connections.Columns[2].Width=110;connections.Columns[3].Width=120;connections.Dock=DockStyle.Fill;card.Controls.Add(connections);Add(stack,card,-1);
   var actions=Row();actions.Controls.Add(Button("断开选中",CloseSelectedConnection,false,116));actions.Controls.Add(Button("断开全部",CloseAllConnections,false,116));Add(stack,actions,52);Add(stack,Label("断开仅结束当前连接，应用可能自动重新连接。来源设备可帮助识别局域网流量。",8,true),34);
